TYPE={'ул':'улица','пер':'переулок','пр-т':'проспект','ш':'шоссе'}

def L(s): return [x.strip() for x in s.split(';') if x.strip()]
C={}  # name -> (group, category, subcategory)
def add(group,cat,sub,names):
    for n in L(names):
        assert n not in C, ('dup',n,C[n])
        C[n]=(group,cat,sub)

