NOTES={'Светланская':'фрегат «Светлана»','Светланский':'по Светланской ул.','Алеутская':'транспорт «Алеут»','Абрекская':'клипер «Абрек»','Паллады':'фрегат «Паллада»','Рюриковская':'крейсер «Рюрик»','Героев Варяга':'экипаж крейсера «Варяг»','Авроровская':'вероятно, фрегат «Аврора»','Американская':'Историческое название главной улицы Владивостока (ныне Светланская): до 1873 г. она называлась Американской — в честь пароходо-корвета «Америка» (судно Сибирской флотилии); в 1873 г. переименована в честь фрегата «Светлана». Источник: https://ru.wikipedia.org/wiki/Светланская_улица','Нейбута':'А.Я. Нейбут, большевик, 1917 г.','Адмирала Юмашева':'командующий ТОФ в войну с Японией','Ватутина':'генерал армии; улица названа в 1950 г.','Сабанеева':'вице-адмирал, нач. политуправления ТОФ 1976–1981','Прапорщика Комарова':'основатель поста Владивосток','Семёновская':'по Я.Л. Семёнову, первому гражданскому жителю (по распространённой версии)','Бархатная':'вероятно, амурский бархат (дерево)','Шошина':'строитель Владивостокской крепости','Окатовая':'местное название','Балтовская':'вероятно, по приморскому селу','Кочубея':'вероятно, И.А. Кочубей, красный командир','Сафонова':'вероятно, лётчик Б.Ф. Сафонов','Корнилова':'персона не установлена','Салтыкова':'парная к ул. Щедрина','Щедрина':'парная к ул. Салтыкова','Зейская':'одна из «речных» улиц Рабочей слободки','Шилкинская':'одна из «речных» улиц Рабочей слободки','Тобольская':'улица Рабочей слободки','Невская':'«речной» квартал в р-не Столетия','Печорская':'«речной» квартал в р-не Столетия','Авраменко':'Улица названа в честь российского революционера Василия Степановича Авраменко (1892–1922), активного борца за установление Советской власти на Дальнем Востоке, умершего во Владивостоке; в 1923 году Интендантская улица на полуострове Шкота была переименована в улицу В. С. Авраменко. Источник: https://ru.wikipedia.org/wiki/Авраменко,_Василий_Степанович','Адмирала Смирнова':'Улица (микрорайон Снеговая Падь, наименование утверждено в 2010 году по предложению командования ТОФ) названа в честь Героя Советского Союза адмирала Николая Ивановича Смирнова (1917–1992), командующего Тихоокеанским флотом с 1969 года, с 1974 года первого заместителя Главнокомандующего ВМФ СССР. Источник: https://vladnews.ru/2010-10-18/17859/vladivostoke_poyavyatsya','Адмирала Угрюмова':'Улица названа в честь адмирала Германа Алексеевича Угрюмова (1948–2001), Героя Российской Федерации, начальника военной контрразведки Тихоокеанского флота, заместителя директора ФСБ России, погибшего в Ханкале (Чечня) 31 мая 2001 года; улица в 94-м военном городке переименована в его честь, открыта мемориальная доска. Источник: https://vladnews.ru/ev/vl/1566/66690/vtoraya_zhizn','Академика Воронова':'Улица названа в честь академика АН СССР Авенира Аркадьевича Воронова (1910–1992), учёного в области теории автоматического управления, возглавлявшего Институт автоматики и процессов управления ДВНЦ АН СССР во Владивостоке. Источник: https://ru.wikipedia.org/wiki/Воронов,_Авенир_Аркадьевич','Анисимова':'Улица (новая, район мыса Чумака, 2000-е) названа в честь командира комсомольско-молодёжного партизанского отряда Михаила Аникеева (1888–1922), прибывшего на Дальний Восток с документами на имя Анисимова; улица получила имя по этим документам. Источник: https://vladnews.ru/ev/vl/1760/73334/propisalsya_chernoy','Баляева':'Улица названа в честь Якова Илларионовича Баляева (1924–1945), рядового-наводчика пулемёта батальона морской пехоты Тихоокеанского флота, Героя Советского Союза (14.09.1945), погибшего 14 августа 1945 года при освобождении корейского города Сейсин (Чонджин). Источник: https://cdt-vlad.ru/?page_id=13967','Баневура':'Улица названа в честь Виталия Борисовича Баневура (Бонивура) (1902/1903–1922), комсомольца, революционера и партизана, одного из руководителей комсомольского подполья во Владивостоке, убитого белоказаками в 1922 году (прототип героя романа «Сердце Бонивура»). Источник: https://ru.wikipedia.org/wiki/Баневур,_Виталий_Борисович','Башидзе':'Улица названа в честь Николая Фёдоровича Башидзе (1898–1922), участника Гражданской войны, большевика, председателя правления профсоюза моряков Владивостокского военного порта (Дальзавода), арестованного и убитого в 1922 году; имя присвоено улице постановлением горсовета 6 ноября 1932 года. Источник: https://argumenti.ru/society/2014/11/459156','Борисенко':'Улица названа в честь Степана Григорьевича Борисенко (1910–1945), артиллериста, командира орудия, Героя Советского Союза, погибшего в 1945 году. Источник: https://cdt-vlad.ru/?page_id=13967','Вилкова':'Улица названа в честь Николая Вилкова, Героя Советского Союза (посмертно), участника войны с Японией; в августе 1945 г. при освобождении курильского острова Шумшу повторил подвиг Александра Матросова (закрыл собой амбразуру). Старшина Тихоокеанского флота. Источник: https://vladlib.ru/n11_09_25_3/','Гассе':'Улица названа в честь контр-адмирала Константина Адольфовича Гассе (1874–1938) — военного моряка и флотского чиновника, участника русско-японской войны и обороны Порт-Артура, служившего во владивостокской портовой конторе с 1900 г.; об этом прямо пишет его потомок в письме в газету. Источник: https://argumenti.ru/society/2015/01/459208','Голицына':'Улица названа в 2015 г. в честь светлейшего князя Дмитрия Владимировича Голицына (1771–1844), генерала от кавалерии, героя Отечественной войны 1812 года. Источник: https://vlad.mk.ru/articles/2015/01/29/vo-vladivostoke-poyavilas-ulica-imeni-knyazya-golicyna.html','Гульбиновича':'Улица названа в память о революционере, герое Гражданской войны Александре Андреевиче Гульбиновиче (1880–1922), рабочем-токаре мастерских Военного порта (Дальзавода), командире 1-й красногвардейской роты и участнике большевистского подполья во Владивостоке; в октябре 1922 г. схвачен контрразведкой и погиб. В 10-ю годовщину гибели героев бывшая Измайловская улица стала улицей Гульбиновича. Источник: https://to-ros.info/?p=54781','Жигура':'Улица названа в честь выходца из Прибалтики Карла Жигура, революционного деятеля, железнодорожника (бывшая Водопроводная улица). Источник: https://vladnews.ru/ev/vl/1935/82369/pravilno_skazat','Ивановская':'Улица появилась в первые десятилетия жизни города в восточной части Владивостока и решением городской думы была названа в честь военного инженера Василия Васильевича Иванова, прибывшего во Владивосток для прохождения службы (строительство оборонительных и портовых сооружений). Источник: https://maxnest.livejournal.com/156024.html','Ильичёва':'Улица названа в честь Петра Ильичёва, краснофлотца, Героя Советского Союза (посмертно); в августе 1945 г. при освобождении курильского острова Шумшу повторил подвиг Александра Матросова. Источник: https://vladlib.ru/n11_09_25_3/','Каплунова':'Улица имени Ильи Каплунова появилась во Владивостоке в 1982 году — в честь воина-тихоокеанца Ильи Макаровича Каплунова (1918–1942), Героя Советского Союза (посмертно, 26.10.1943); в декабре 1942 г. под Сталинградом уничтожил восемь вражеских танков и ценой жизни девятый. Источник: https://vladnews.ru/ev/vl/2684/18245/ulica_imeni','Колесника':'Улица Колесника (бывшая Верхне-Ишимская) названа в честь Героя Советского Союза Василия Колесника: в бою с японскими милитаристами в августе 1945 г. он закрыл своим телом амбразуру вражеского дота (погиб 10.08.1945 под Мишанью). Источник: https://russiancip.ru/map/points/memorialnaya-doska-vs-kolesniku','Котельникова':'Улица названа в честь Валентина Сергеевича Котельникова (1911–1935), пограничника, командир отделения дальневосточной заставы «Волынка», погибшего в 1935 году в неравном бою с японцами; его имя носит улица во Владивостоке и застава Камень-Рыболовского погранотряда. Источник: https://vestiprim.ru/news/ptrnews/27787-v-primore-pochtili-pamyat-valentina-kotelnikova.html'}
UNSURE=set(L('Авроровская;Семёновская;Бархатная;Окатовая;Балтовская;Кочубея;Сафонова;Рифовая;Новоивановская;Русская;Медовая;Нектарная;Пасечная;Опорная;Щитовая;Фонтанная;Подъемная;Комитетская;Артековская;Полярная;Канатный;Басаргина;Бурачка;Надибаидзе;Майора Филипова;Полковника Фесюна;Профессора Шапкина'))

CONFIRMED=set(L('Котельникова'))  # опознаны (V2, уверенно); подтема не менялась: Махалина/Котельникова — перенос решает владелец
rows=[];miss=[]
for t,n in raw:
    if n not in C: miss.append(n); continue
    g,c,s=C[n]
    conf='нужна проверка' if ((g==G_P and c=='Местные деятели и неустановленные') or g==G_X or n in UNSURE) and n not in CONFIRMED else 'высокая'
    rows.append(dict(name=n,type=TYPE[t],group=g,cat=c,sub=s,conf=conf,note=NOTES.get(n,'')))
unused=[k for k in C if k not in {n for _,n in raw}]
print('rows',len(rows),'missing',miss,'unused',unused)
json.dump(rows,open(os.path.join(HERE,'rows.json'),'w',encoding='utf-8'),ensure_ascii=False)
